sys_script_email.script:
(function runMailScript(/* GlideRecord */ current, /* TemplatePrinter */ template,
          /* Optional EmailOutbound */ email, /* Optional GlideRecord */ email_action,
          /* Optional GlideRecord */ event) {

	// Return the URL to access the current Telework Agreement record in the portal
	var url = gs.getProperty("glide.servlet.uri") + "services?id=standard_ticket&amp;table=x_hccc_hoc_ohs_telework_agreement&amp;sys_id=" + current.getUniqueValue().toString();
	url = url + "&amp;view=sp&amp;lang=en";

	template.print(url);

})(current, template, email, email_action, event);
